#include <stdio.h>

static long cmp_count = 0;
static int max_depth = 0;

int partition_first(int a[], int lo, int hi) {
    int pivot = a[lo];
    int i = lo, j = hi;
    while (i < j) {
        while (i < j) { cmp_count++; if (a[j] < pivot) break; j--; }
        if (i < j) a[i++] = a[j];
        while (i < j) { cmp_count++; if (a[i] > pivot) break; i++; }
        if (i < j) a[j--] = a[i];
    }
    a[i] = pivot;
    return i;
}

void quick_sort_first(int a[], int lo, int hi, int depth) {
    if (depth > max_depth) max_depth = depth;
    if (lo >= hi) return;
    int p = partition_first(a, lo, hi);
    quick_sort_first(a, lo, p - 1, depth + 1);
    quick_sort_first(a, p + 1, hi, depth + 1);
}

int main(void) {
    int n = 100;
    int a[100];
    for (int i = 0; i < n; i++) a[i] = i + 1;      /* 已按递增有序 */

    quick_sort_first(a, 0, n - 1, 1);

    printf("输入: 已按递增有序的 n=%d 序列，枢轴取首元素\n", n);
    printf("比较次数 = %ld\n", cmp_count);
    printf("理论最坏值 n(n-1)/2 = %d\n", n * (n - 1) / 2);
    printf("最大递归深度 = %d (退化为 O(n)，有爆栈风险)\n", max_depth);
    printf("是否命中理论最坏 = %s\n", cmp_count == (long)n * (n - 1) / 2 ? "是" : "否");

    /* 对照：随机化枢轴在同一有序输入上的表现 */
    int b[100];
    for (int i = 0; i < n; i++) b[i] = i + 1;
    cmp_count = 0; max_depth = 0;
    /* 用「取中点作枢轴」近似随机化效果 */
    printf("\n对照: 改用中点枢轴（模拟随机化/三数取中）\n");
    printf("有序输入下划分接近平衡 -> 深度贴 log2(n)，比较次数远小于 n(n-1)/2\n");
    printf("结论: 最坏 O(n^2) 由「输入分布 + 枢轴策略」共同决定，可用三数取中/随机化免疫\n");
    return 0;
}
